  chip->fw_build_time[sizeof(chip->fw_build_time) - 1] = '\0';
  chip->fw_wifi_ver[sizeof(chip->fw_wifi_ver) - 1] = '\0';
  chip->fw_plat_ver[sizeof(chip->fw_plat_ver) - 1] = '\0';
