         chip->calib_module_id, (FAR char *)chip->fw_wifi_ver,
         (FAR char *)chip->fw_plat_ver, (FAR char *)chip->fw_build_time);
  syslog(LOG_INFO, "SKW WiFi: MAC %02x:%02x:%02x:%02x:%02x:%02x, "
