    {
      nxmutex_unlock(&g_op_lock);
      return -EAGAIN;
    }

  for (i = 0; i < g_nbss; i++)
    {
      if (wlan_iw_put_bss(iwr->u.data.pointer, iwr->u.data.length, &off,
