/*
 * KICKPI-K7 AMP：哪个镜像跑在哪颗核上。
 *
 * 这份 FIT 是 AMP 的**全部契约**。U-Boot（drivers/cpu/rockchip_amp.c）
 * 读它，按 cpu 属性里的 MPIDR 把核分掉：
 *
 *   cpu = <0x000>  A53 簇 core0 —— 也就是 U-Boot 自己正跑在上面的那颗。
 *                  它是"boot cpu"，U-Boot 不会 PSCI 拉它，而是在最后
 *                  armv8_switch_to_el2() 直接跳进去。openvela 走这条路。
 *   cpu = <0x100>  A72 簇 core0。U-Boot 用 PSCI CPU_ON 把它拉起来跑 Linux。
 *
 * 两个簇里剩下的三颗核**不在这里**：各自的 OS 起来以后自己拉
 * （openvela 的 SMP 走 arm64_cpustart.c，Linux 走它的 DTB）。
 *
 * ★ Linux 的镜像不在这份 FIT 里
 *
 *   rockchip_amp.c 的 load_linux_for_nonboot_cpu() 是去跑 `boot_fit` /
 *   `boot_android`，也就是**走正常启动流程从 boot 分区读**。所以 linux
 *   节点只描述"跑在哪颗核、什么执行状态"，镜像本身在 boot 分区的
 *   boot.img 里（见 amp/linux/ 和 scripts/repack-bootimg.py）。
 *
 * ★ 顺序是 Linux 先起
 *
 *   brought_up_all_amp() 先处理 linux 节点，再处理 loadables，最后才把
 *   当前核送进 openvela。这个顺序是必须的：GIC 的 distributor 归 Linux，
 *   它得先配完，openvela 那边才能带着
 *   CONFIG_ARM64_GICV2_SHARED_DIST=y 接着用。
 *
 * 打包：
 *   mkimage -f amp.its -E -p 0xe00 amp.itb
 */

/dts-v1/;
/ {
	description = "KICKPI-K7 AMP: openvela on A53 cluster, Linux on A72 cluster";
	#address-cells = <1>;

	images {
		openvela {
			description  = "openvela (NuttX) on A53 cluster";
			data         = /incbin/("./openvela-amp.bin");
			type         = "firmware";	/* 必须是 firmware */
			compression  = "none";
			arch         = "arm64";
			cpu          = <0x000>;		/* MPIDR：A53 core0 = 启动核 */
			thumb        = <0>;
			hyp          = <0>;		/* EL1。NuttX 自己会降到 EL1 */
			load         = <0x4a400000>;	/* = CONFIG_RAM_START */
			hash {
				algo = "sha256";
			};
		};
	};

	configurations {
		default = "conf";
		conf {
			description = "openvela + Linux";
			loadables = "openvela";

			/*
			 * Linux 跑 A72 簇 core0。地址由 U-Boot 的
			 * kernel_addr_r / fdt_addr_r / ramdisk_addr_r 决定，
			 * 这里给 load 会覆盖 kernel_addr_r。
			 */
			linux {
				description  = "Linux on A72 cluster";
				arch         = "arm64";
				cpu          = <0x100>;
				thumb        = <0>;
				hyp          = <0>;
				/* ★ 越小越好：这段延时全部落在"Linux 已经在跑、
				 * U-Boot 还没跳进 openvela"这个窗口里，而
				 * Linux 的页分配器随时可能动到 U-Boot 占的
				 * 内存。DTB 里已经把那一段 reserved 掉，这里
				 * 再把窗口压到最短，两层一起防。
				 */
				udelay       = <0>;
			};
		};
	};
};
	printf("AMP: lxroot %u 字节 @0x%x，sha256 一致（读+校验 %lu ms）\n",
	       hdr.length, AMP_LXROOT_ADDR, get_timer(t0));
}

/*
 * ★ 读完 FIT 先核对它**实际需要多长**，超出读取窗口就明说。
 *
 *   这个窗口曾经是 5120 扇区，镜像涨到 5177 / 5561 扇区后，
 *   无参数 bootamp 读进来的是截断的 FIT，报的却是
 *
 *       Verifying Hash Integrity ... sha256 Bad hash
 *       Bad Data Hash / AMP Error: Load loadables, ret=-13
 *
 *   看起来像"镜像写坏了"，其实写入和回读都是对的，是引导器少读了尾巴。
 *   这个坑踩了两次：一次是 LVGL 静态缓冲撑大镜像，一次是加网络 NSH。
 *   而且仓库里的补丁改了上限、U-Boot 源码却没改，也没重编 ——
 *   上限值被写在两个地方，只改一处就会出现"以为修了其实没有"。
 *
 *   mkimage -E -p 生成的是外置数据的 FIT：FDT 头之后才是各镜像的数据，
 *   每个镜像节点里有 data-position（绝对偏移）和 data-size。取其中最大的
 *   结束位置，就是整个 FIT 需要读进来的长度。
 */
static int amp_check_fit_window(void *fit, ulong window)
{
	ulong need;
	int images, node;

	if (fdt_check_header(fit)) {
		printf("AMP: FIT 头无效（LBA 0x%x 处不是 FIT）\n", AMP_FIT_LBA);
		return -EINVAL;
	}

	need = fdt_totalsize(fit);
	images = fdt_path_offset(fit, FIT_IMAGES_PATH);
	if (images >= 0) {
		fdt_for_each_subnode(node, fit, images) {
			int pos, size;

			if (fit_image_get_data_size(fit, node, &size))
				continue;
			if (fit_image_get_data_position(fit, node, &pos) &&
			    fit_image_get_data_offset(fit, node, &pos))
				continue;
			/* data-offset 是相对 FDT 末尾（按 4 字节对齐）的 */
			if (!fdt_getprop(fit, node, FIT_DATA_POSITION_PROP, NULL))
				pos += ALIGN(fdt_totalsize(fit), 4);
			if ((ulong)pos + size > need)
				need = (ulong)pos + size;
		}
	}

	printf("AMP: FIT 需要 %lu 字节（%lu 扇区），读取窗口 %lu 扇区\n",
	       need, (need + 511) / 512, window / 512);

	if (need > window) {
		printf("AMP: ★ FIT 超过读取窗口，读进来的镜像不完整，\n"
		       "     后面的哈希校验必然失败。请缩小镜像或调大 AMP_FIT_CNT\n"
		       "     （上限 8192 扇区，再大就会压到 LBA 32768 的 misc）。\n");
		return -E2BIG;
	}

	return 0;
}

static int amp_load_from_mmc(void)
{
	char cmd[128];
	int ret;

	ret = run_command("mmc dev 0", 0);
	if (ret)
		return ret;

	snprintf(cmd, sizeof(cmd), "mmc read 0x%x 0x%x 0x%x",
		 AMP_KERNEL_ADDR, AMP_KERNEL_LBA, AMP_KERNEL_CNT);
	ret = run_command(cmd, 0);
	if (ret)
		return ret;

	snprintf(cmd, sizeof(cmd), "mmc read 0x%x 0x%x 0x%x",
		 AMP_DTB_ADDR, AMP_DTB_LBA, AMP_DTB_CNT);
	ret = run_command(cmd, 0);
	if (ret)
		return ret;

	snprintf(cmd, sizeof(cmd), "mmc read 0x%x 0x%x 0x%x",
		 AMP_FIT_ADDR, AMP_FIT_LBA, AMP_FIT_CNT);
	ret = run_command(cmd, 0);
	if (ret)
		return ret;

	ret = amp_check_fit_window((void *)(ulong)AMP_FIT_ADDR,
				   (ulong)AMP_FIT_CNT * 512);
	if (ret)
		return ret;

	/* ★ devtype/devnum 必须有值，否则 booti 会在 strcmp(NULL) 上炸
	 *
	 *   common/bootm.c 的 bootm_disable_interrupts() 里是
	 *
	 *       if (!strcmp(env_get("devtype"), "usb"))
	 *
	 *   没有判空。平时这两个变量由 setup_boot_dev() 设好，但关掉
	 *   CONFIG_USING_KERNEL_DTB 之后（见 0005 补丁）它跑在环境变量初始化
	 *   **之前** —— 日志里是 `Bootdev(atags): <NULL> <NULL>`，而原来是
	 *   `Bootdev(atags): mmc 0`。于是 env_get 返回 NULL，booti 走到
	 *   bootm_disable_interrupts() 就 data abort：
	 *
	 *       "Synchronous Abort" handler, esr 0x96000006
	 *       PC = strcmp+8, x0 = 0, x1 -> "usb"
	 *
	 *   我们这条路本来就是从 eMMC 读的，直接把真实值补上。
	 *   （bootm.c 那个判空也一并修了，见同一份补丁。）
	 */

	env_set("devtype", "mmc");
	env_set("devnum", "0");

	amp_load_lxroot();

	/* 已经设过就不动 —— 手工覆盖优先于默认值。 */

	if (!env_get("amp_linux_cmd")) {
		snprintf(cmd, sizeof(cmd), "booti 0x%x - 0x%x",
			 AMP_KERNEL_ADDR, AMP_DTB_ADDR);
		env_set("amp_linux_cmd", cmd);
	}

	printf("AMP: loaded kernel@0x%x dtb@0x%x fit@0x%x from eMMC\n",
	       AMP_KERNEL_ADDR, AMP_DTB_ADDR, AMP_FIT_ADDR);

	return 0;
}

static int do_bootamp(cmd_tbl_t *cmdtp, int flag, int argc, char *const argv[])
{
	void *fit;
	int ret;

	if (argc > 2)
		return CMD_RET_USAGE;

	if (argc == 1) {
		ret = amp_load_from_mmc();
		if (ret) {
			printf("AMP: load from eMMC failed, ret=%d\n", ret);
			return CMD_RET_FAILURE;
		}

		fit = (void *)AMP_FIT_ADDR;
	} else {
		fit = (void *)simple_strtoul(argv[1], NULL, 16);
	}

	printf("AMP: booting from FIT at %p\n", fit);

	ret = amp_cpus_on_at(fit);

	/* 到这里说明没起来 —— 成功的话当前核已经跳走了。 */

	printf("AMP: failed, ret=%d (板子仍在 U-Boot，可以重来)\n", ret);

	return CMD_RET_FAILURE;
}

U_BOOT_CMD(
	bootamp, 2, 0, do_bootamp,
	"boot the AMP pair (openvela on A53 + Linux on A72)",
	"\n"
	"    - no argument: read kernel/dtb/FIT from eMMC, then boot\n"
	"bootamp <addr>\n"
	"    - <addr>: hex address of an AMP FIT already in memory\n"
	"\n"
	"The FIT describes which image runs on which CPU (by MPIDR).\n"
	"On success this command does not return: the current CPU enters\n"
	"the image whose 'cpu' property matches its own MPIDR.\n"
);

/****************************************************************************
 * app/lxroot/lxroot_main.c
