231:  long                   write_ms;  /* 花在写 eMMC 上的时间，其余是等网络 */
232:  struct timespec        t0;
233:  mbedtls_sha256_context sha;
234:};
235:
236:static void sha_hex(FAR const uint8_t *d, FAR char *out)
237:{
238:  int i;
239:
240:  for (i = 0; i < 32; i++)
241:    {
242:      sprintf(out + i * 2, "%02x", d[i]);
243:    }
244:}
245:
246:static int parse_sha(FAR const char *hex, FAR uint8_t *out)
247:{
248:  int i;
249:
250:  if (strlen(hex) != 64)
251:    {
252:      return -EINVAL;
253:    }
254:
255:  for (i = 0; i < 32; i++)
256:    {
257:      unsigned int v;
258:
259:      if (sscanf(hex + i * 2, "%2x", &v) != 1)
260:        {
261:          return -EINVAL;
262:        }
263:
264:      out[i] = (uint8_t)v;
265:    }
266:
267:  return 0;
268:}
269:
270:static int dl_flush(FAR struct lxroot_dl_s *dl)
271:{
272:  struct timespec t0;
273:  ssize_t n;
274:
275:  if (dl->fill == 0)
276:    {
277:      return 0;
278:    }
279:
280:  clock_gettime(CLOCK_MONOTONIC, &t0);
281:  n = write(dl->fd, dl->chunk, dl->fill);
282:  dl->write_ms += elapsed_ms(&t0);
283:  if (n != (ssize_t)dl->fill)
284:    {
285:      return n < 0 ? -errno : -EIO;
286:    }
287:
288:  dl->fill = 0;
289:  return 0;
290:}
291:
292:static int dl_sink(FAR char **buffer, int offset, int datend,
293:                   FAR int *buflen, FAR void *arg)
294:{
295:  FAR struct lxroot_dl_s *dl = arg;
296:  FAR const uint8_t *p = (FAR const uint8_t *)*buffer + offset;
297:  uint32_t len = (uint32_t)(datend - offset);
298:
299:  (void)buflen;
300:
301:  if (len > dl->want - dl->got)
302:    {
303:      dl->err = -EFBIG;
304:      return -EFBIG;
305:    }
306:
307:  mbedtls_sha256_update(&dl->sha, p, len);
308:  dl->got += len;
309:
310:  while (len > 0)
311:    {
312:      uint32_t n = LXROOT_CHUNK - dl->fill;
313:
314:      if (n > len)
315:        {
316:          n = len;
317:        }
318:
319:      memcpy(dl->chunk + dl->fill, p, n);
320:      dl->fill += n;
321:      p += n;
322:      len -= n;
323:
324:      if (dl->fill == LXROOT_CHUNK)
325:        {
326:          dl->err = dl_flush(dl);
327:          if (dl->err < 0)
328:            {
329:              return dl->err;
330:            }
331:        }
332:    }
333:
334:  if (dl->got >= dl->report)
335:    {
336:      printf("  已收 %" PRIu32 " MB，%ld s\n", dl->got >> 20,
337:             elapsed_ms(&dl->t0) / 1000);
338:      dl->report += LXROOT_REPORT;
339:    }
340:
341:  return 0;
342:}
343:
344:/* 从分区回读本体并算 sha256。重新打开设备，读的是 eMMC 上的内容 */
345:
346:static int readback_sha(uint32_t data_sector, uint32_t length,
347:                        FAR uint8_t *out)
348:{
349:  mbedtls_sha256_context sha;
350:  FAR uint8_t *buf;
351:  uint32_t left = length;
352:  uint32_t nsect;
353:  int ret = 0;
354:  int fd;
355:
356:  fd = lxroot_open(O_RDONLY, &nsect);
357:  if (fd < 0)
358:    {
359:      return -ENODEV;
360:    }
361:
362:  buf = malloc(LXROOT_CHUNK);
363:  if (buf == NULL)
364:    {
365:      close(fd);
366:      return -ENOMEM;
367:    }
368:
369:  mbedtls_sha256_init(&sha);
370:  mbedtls_sha256_starts(&sha, 0);
371:
372:  if (lseek(fd, (off_t)data_sector * LXROOT_SECTOR, SEEK_SET) < 0)
373:    {
374:      ret = -errno;
375:    }
376:
377:  while (ret == 0 && left > 0)
378:    {
379:      uint32_t n = left > LXROOT_CHUNK ? LXROOT_CHUNK : left;
380:      ssize_t r = read(fd, buf, n);
381:
382:      if (r != (ssize_t)n)
383:        {
384:          ret = r < 0 ? -errno : -EIO;
385:          break;
386:        }
387:
388:      mbedtls_sha256_update(&sha, buf, n);
389:      left -= n;
390:    }
391:
392:  mbedtls_sha256_finish(&sha, out);
393:  mbedtls_sha256_free(&sha);
394:  free(buf);
395:  close(fd);
396:  return ret;
397:}
398:
399:static int read_hdr(FAR struct k7lx_hdr_s *h, FAR uint32_t *nsect)
400:{
401:  uint8_t buf[LXROOT_SECTOR];
402:  int ret;
403:  int fd;
404:
405:  fd = lxroot_open(O_RDONLY, nsect);
406:  if (fd < 0)
407:    {
408:      return -ENODEV;
409:    }
410:
411:  ret = rw_sector(fd, 0, buf, false);
412:  close(fd);
413:  if (ret < 0)
414:    {
415:      return ret;
416:    }
417:
418:  memcpy(h, buf, sizeof(*h));
419:  return 0;
420:}

