// SPDX-License-Identifier: GPL-2.0+
/*
 * bootamp - 从内存里的 AMP FIT 启动双 OS
 *
 * Copyright (c) 2026 contest2026_423_nanshannan
 *
 * 用法：
 *	bootamp			—— 自己从 eMMC 把三块料读进来再启动
 *	bootamp <FIT 地址>	—— FIT 已经在内存里，只负责启动
 *
 * ★ 为什么加了不带参数的那一种
 *
 *   原来每轮都要在串口上敲六条命令：mmc dev / 三条 mmc read / setenv
 *   amp_linux_cmd / bootamp。1.5M 波特率没有流控，实测**会丢字节** ——
 *   有一次 `setenv amp_linux_cmd 'booti 0x40400000 - 0x4f000000'` 到板子
 *   那边成了 `booti 0x4f000000`，于是 U-Boot 拿 dtb 当内核启动，data
 *   abort，板子挂死到只能按 RESET。
 *
 *   这类事故的根因不是哪条命令写错了，而是**每轮要在易错通道上传六条
 *   长命令**。把布局写进代码，一条 `bootamp` 就够，出错面积小一个数量级。
 *   挪位置就改下面那几个宏（和 amp/FLASH.md 那张表一起改）；如果之前
 *   已经手工 setenv 过 amp_linux_cmd，这条命令不会覆盖它。
 *
 * ★ 这条命令不会返回。
 *
 *   brought_up_all_amp() 的最后一步是把**当前这颗核**送进 FIT 里
 *   cpu = <当前 MPIDR> 的那个镜像（armv8_switch_to_el2）。所以它成功了
 *   就再也回不来，失败才返回 —— 返回值非 0 一定是出错。
 *
 * ★ 为什么做成手动命令而不是挂进 bootcmd
 *
 *   AMP 起不来的时候，板子必须还能进普通系统。默认 bootcmd 保持不变，
 *   下一次上电就是原来的样子；要试 AMP 就在 U-Boot 提示符下显式敲。
 *   调试期不能把唯一的退路也押上去。
 */

#include <common.h>
#include <amp.h>
#include <command.h>
#include <environment.h>
#include <fdt_support.h>
#include <image.h>
#include <linux/libfdt.h>
#include <u-boot/sha256.h>

/* eMMC 上的默认布局，和仓库 amp/layout.sh 一一对应（主机脚本以那边为准）。
 *
 * 扇区数取的是**上限**而不是精确值：多读几个扇区没有副作用，而写死精确
 * 值意味着每次镜像变大都要同步改两处（这里和文档），漏一处就是"读进来
 * 的 FIT 少了尾巴"这种很难看出来的故障。上限都留在各自分区内：
 *   FIT  24576 + 8192 = 32768 = misc 起点（trust 分区整段，不越界）
 *   dtb  14336 +  544 = 14880 < 16384（uboot 分区）
 *   内核 49152 +16384 = 65536 = rkdeveloptool 写得到的上限（不越界）
 *
 * ★ 内核窗口原来是 14848 扇区（7.25MB）。2026-10-31 内核打开 MODULES 和
 *   IOMMU（摄像头驱动编成模块放进 lxroot）后 Image 涨到 7.4MB，放宽到
 *   65536 为止的整段 8MB。64000..65535 之前没有任何东西。
 *
 * ★ FIT 原来在 security 分区（LBA 8192，上限 6144 扇区 = 3MB，顶到 dtb）。
 *   挪到 trust 有两个原因：openvela 还会继续变大；security 是 OP-TEE
 *   安全存储（RKSS）的分区，每次启动日志都有 `TEEC: Reset area[0]/[1]`，
 *   碰的正是 8192/9216。trust 在本板的 FIT 版 uboot.img 下没有用途，
 *   U-Boot 也不写它（amp/FLASH.md 实测）。
 */

#define AMP_FIT_LBA		0x6000		/* 24576（trust 分区） */
#define AMP_FIT_CNT		0x2000		/*  8192 扇区 = 4MB 上限 */
#define AMP_DTB_LBA		0x3800		/* 14336 */
#define AMP_DTB_CNT		0x220		/*   544 扇区 = 272KB 上限 */
#define AMP_KERNEL_LBA		0xC000		/* 49152 */
#define AMP_KERNEL_CNT		0x4000		/* 16384 扇区 = 8MB 上限 */

#define AMP_FIT_ADDR		0x60000000
#define AMP_DTB_ADDR		0x4f000000
#define AMP_KERNEL_ADDR		0x40400000

/*
 * A72 上 Linux 的外部根文件系统镜像（openvela 的 `lxroot write` 写进来）。
 *
 *   分区：出厂 GPT 的 backup，LBA 378880 起 786432 扇区（384MB）。
 *   格式：仓库 amp/include/k7_lxroot.h —— 扇区 0 是头部，本体从扇区 8 起。
 *   这里抄一份结构，两边改一处就要改另一处。
 *
 * 读进 AMP_LXROOT_ADDR，sha256 对上之后写进内核 dtb 的 /chosen
 * linux,initrd-start/end。内核先解内嵌的 initramfs，再把这份 cpio 解在
 * 上面（同名文件覆盖）。
 *
 * ★ 任何一步不对都**不阻止启动**，只是不带外部镜像 —— 和没有这一段时
 *   完全一样。头部最后写、只在校验通过后写（见 k7_lxroot.h），所以半截
 *   的镜像在这里看到的是无效头部。
 *
 * 0x80000000 起 384MB：离 FIT（0x60000000）、内核、dtb、openvela
 * （0x4a400000）、帧共享区（0x50000000）都远，也远在 U-Boot 自己
 * （0xf0000000 以上）之下。Linux 按 /chosen 里的范围自己 memblock 保留。
 */
#define AMP_LXROOT_LBA		0x5C800		/* 378880 */
#define AMP_LXROOT_CNT		0xC0000		/* 786432 扇区 = 384MB */
#define AMP_LXROOT_ADDR		0x80000000
#define K7LX_MAGIC		"K7LXROOT"
#define K7LX_DATA_SECTOR	8

struct k7lx_hdr_s {
	char	magic[8];
	u32	version;
	u32	data_sector;
	u32	length;
	u32	reserved;
	u8	sha256[32];
};

static void amp_load_lxroot(void)
{
	struct k7lx_hdr_s hdr;
	u8 sum[SHA256_SUM_LEN];
	void *fdt = (void *)AMP_DTB_ADDR;
	ulong max = (ulong)(AMP_LXROOT_CNT - K7LX_DATA_SECTOR) * 512;
	ulong t0;
	char cmd[128];
	int ret;

	if (env_get("amp_lxroot") && !strcmp(env_get("amp_lxroot"), "off")) {
		printf("AMP: lxroot 已由 amp_lxroot=off 关闭\n");
		return;
	}

	snprintf(cmd, sizeof(cmd), "mmc read 0x%x 0x%x 1",
		 AMP_LXROOT_ADDR, AMP_LXROOT_LBA);
	if (run_command(cmd, 0)) {
		printf("AMP: lxroot 头部读不出来，不带外部镜像\n");
		return;
	}

	memcpy(&hdr, (void *)AMP_LXROOT_ADDR, sizeof(hdr));
	if (memcmp(hdr.magic, K7LX_MAGIC, 8) || hdr.version != 1 ||
