68	static void set_ready(void* data)
69	{
70	    loop_priv_t* priv = data;
71	
72	    priv->is_running = 1;
73	    uv_sem_init(&priv->exited, 0);
74	    uv_sem_post(&priv->ready);
75	    syslog(LOG_DEBUG, "set_ready");
76	}
