81	    loop_priv_t* priv = loop->data;
82	
83	    priv->is_running = 0;
84	    uv_close((uv_handle_t*)&priv->async, NULL);
85	    uv_stop(loop);
86	    syslog(LOG_DEBUG, "set_stopped");
87	}
