102	    for (;;) {
103	        uv_mutex_lock(&priv->msg_lock);
104	        imsg = (internel_msg_t*)list_remove_head(&priv->msg_queue);
105	        uv_mutex_unlock(&priv->msg_lock);
106	        if (!imsg)
107	            return;
108	
