171	int thread_loop_run(uv_loop_t* loop, bool start_thread, const char* name)
172	{
173	    loop_priv_t* priv = loop->data;
174	
175	    if (start_thread) {
176	        int ret = uv_sem_init(&priv->ready, 0);
177	        if (ret != 0) {
178	            syslog(LOG_ERR, "%s sem init error: %d", __func__, ret);
179	            return ret;
180	        }
181	
182	        uv_thread_options_t options = {
183	            UV_THREAD_HAS_STACK_SIZE | UV_THREAD_HAS_PRIORITY,
184	            LOOP_THREAD_STACK_SIZE,
185	            CONFIG_BLUETOOTH_SERVICE_LOOP_THREAD_PRIORITY
186	        };
187	        ret = uv_thread_create_ex(&priv->thread, &options, thread_schedule_loop, (void*)loop);
188	        if (ret != 0) {
189	            syslog(LOG_ERR, "loop thread create :%d", ret);
190	            return ret;
191	        }
192	
193	        if (name != NULL && strlen(name) > 0)
194	            snprintf(priv->name, sizeof(priv->name), "%s_%d", name, getpid());
195	        else
196	            snprintf(priv->name, sizeof(priv->name), "loop_%d", getpid());
197	        pthread_setname_np(priv->thread, priv->name);
198	        uv_sem_wait(&priv->ready);
199	        uv_sem_destroy(&priv->ready);
200	        syslog(LOG_DEBUG, "%s loop running now !!!", priv->name);
201	    } else {
202	        syslog(LOG_DEBUG, "%s loop running now !!!", name);
203	        thread_schedule_loop(NULL);
204	    }
205	
206	    return 0;
207	}
