209	void thread_loop_exit(uv_loop_t* loop)
210	{
211	    struct list_node* node;
212	    struct list_node* tmp;
213	
214	    if (!loop || !loop->data)
215	        return;
216	
217	    loop_priv_t* priv = loop->data;
218	
219	    if (priv->is_running) {
220	        do_in_thread_loop(loop, set_stop, (void*)loop);
221	        uv_sem_wait(&priv->exited);
222	        uv_sem_destroy(&priv->exited);
223	    } else {
224	        uv_run(loop, UV_RUN_ONCE);
225	        (void)uv_loop_close(loop);
226	    }
227	
228	    uv_mutex_lock(&priv->msg_lock);
229	    list_for_every_safe(&priv->msg_queue, node, tmp)
230	    {
231	        list_delete(node);
232	        free(node);
233	    }
234	    list_delete(&priv->msg_queue);
235	    uv_mutex_unlock(&priv->msg_lock);
236	    uv_mutex_destroy(&priv->msg_lock);
237	    free(priv);
238	}
