243	    assert(cb);
244	
245	    uv_poll_t* handle = (uv_poll_t*)malloc(sizeof(uv_poll_t));
246	    if (!handle)
247	        return NULL;
248	
249	    handle->data = userdata;
250	    int ret = uv_poll_init(loop, handle, fd);
251	    if (ret != 0)
