314	void do_in_thread_loop(uv_loop_t* loop, thread_func_t func, void* data)
315	{
316	    loop_priv_t* priv = loop->data;
317	    internel_msg_t* msg = (internel_msg_t*)malloc(sizeof(internel_msg_t));
318	    assert(msg);
319	
320	    msg->func = func;
321	    msg->msg = data;
322	
323	    uv_mutex_lock(&priv->msg_lock);
324	    list_add_tail(&priv->msg_queue, &msg->node);
325	    uv_mutex_unlock(&priv->msg_lock);
326	
327	    uv_async_send(&priv->async);
328	}
