363	static void bt_rxq_cb(FAR void *arg, uint8_t type,
364	                      FAR const uint8_t *data, size_t len)
365	{
366	  FAR struct skw_btdev_s *dev = arg;
367	  FAR struct bt_rxpkt_s *pkt;
368	
369	  if ((type != 0x04 && type != 0x02) || len > BT_RXQ_SIZE ||
370	      dev->rxn >= BT_RXQ_DEPTH)
371	    {
372	      dev->dropped++;
373	      return;
374	    }
375	
376	  pkt = &dev->rxq[dev->rxn++];
377	  pkt->type = type;
378	  pkt->len = len;
379	  memcpy(pkt->data, data, len);
380	}
381	
382	static int bt_rx_thread(int argc, FAR char *argv[])
383	{
384	  FAR struct skw_btdev_s *dev = &g_skwbt;
385	  unsigned int last_dropped = 0;
386	
387	  while (dev->running)
388	    {
389	      unsigned int i;
390	      int ret;
391	
392	      ret = skw6621s_poll();
393	      if (ret < 0)
394	        {
395	          syslog(LOG_ERR, "SKW BT: rx poll %d, RX thread stops\n", ret);
396	          break;
397	        }
398	
399	      /* The callback ran inside skw6621s_poll(); the lock is free now */
400	
401	      for (i = 0; i < dev->rxn; i++)
402	        {
403	          FAR struct bt_rxpkt_s *pkt = &dev->rxq[i];
404	
405	          bt_netdev_receive(&dev->drv,
406	                            pkt->type == 0x04 ? BT_EVT : BT_ACL_IN,
407	                            pkt->data, pkt->len);
408	        }
409	
410	      dev->rxn = 0;
411	
412	      if (dev->dropped != last_dropped)
413	        {
414	          syslog(LOG_WARNING, "SKW BT: dropped %u rx packets\n",
415	                 dev->dropped);
416	          last_dropped = dev->dropped;
417	        }
418	
419	      if (ret == 0)
420	        {
421	          nxsig_usleep(BT_RX_IDLE_US);
422	        }
423	    }
424	
425	  dev->running = false;
426	  return 0;
427	}
428	
429	static int skwbt_open(FAR struct bt_driver_s *drv)
430	{
431	  FAR struct skw_btdev_s *dev = &g_skwbt;
432	  int ret;
433	
434	  if (dev->running)
435	    {
436	      return OK;
437	    }
438	
439	  /* Vendor init with the synchronous path, before the RX thread owns
440	   * the receive side.
441	   */
442	
443	  ret = skw6621s_bt_hci_init(dev->nvpath);
444	  if (ret < 0)
445	    {
446	      return ret;
447	    }
448	
449	  dev->rxn = 0;
450	  skw6621s_set_hci_cb(bt_rxq_cb, dev);
451	
452	  dev->running = true;
453	  dev->pid = kthread_create("skwbt_rx", 120, 4096, bt_rx_thread, NULL);
454	  if (dev->pid < 0)
455	    {
456	      dev->running = false;
457	      skw6621s_set_hci_cb(NULL, NULL);
458	      return dev->pid;
459	    }
460	
461	  return OK;
462	}
463	
464	static int skwbt_send(FAR struct bt_driver_s *drv, enum bt_buf_type_e type,
465	                      FAR void *data, size_t len)
466	{
467	  int ret;
468	
469	  if (type == BT_CMD)
470	    {
471	      ret = skw6621s_hci_send(0x01, data, len);
472	    }
473	  else if (type == BT_ACL_OUT)
474	    {
475	      ret = skw6621s_hci_send(0x02, data, len);
476	    }
477	  else
478	    {
479	      return -EINVAL;
480	    }
481	
482	  return ret < 0 ? ret : (int)len;
483	}
484	
485	static void skwbt_close(FAR struct bt_driver_s *drv)
486	{
487	  g_skwbt.running = false;
488	}
489	
490	int skw6621s_bt_register(FAR const char *nvpath)
491	{
492	  FAR struct skw_btdev_s *dev = &g_skwbt;
493	
494	  if (dev->drv.open != NULL)
495	    {
496	      return -EALREADY;
497	    }
498	
499	  dev->nvpath     = nvpath;
500	  dev->drv.open   = skwbt_open;
501	  dev->drv.send   = skwbt_send;
502	  dev->drv.close  = skwbt_close;
503	
504	  return bt_driver_register(&dev->drv);
505	}
