static void hci_core_send_cmd(struct bt_dev *hdev)
{
	struct net_buf *buf;
	int err;

	/* Get next command */
	LOG_DBG("dev:%d, fetch cmd", hdev->dev_id);
	buf = k_fifo_get(&hdev->cmd_tx_queue, K_NO_WAIT);
	BT_ASSERT(buf);

	/* Clear out any existing sent command */
	if (hdev->sent_cmd) {
		LOG_ERR("Uncleared pending sent_cmd");
		net_buf_unref(hdev->sent_cmd);
		hdev->sent_cmd = NULL;
	}

	hdev->sent_cmd = net_buf_ref(buf);

	LOG_DBG("Sending command 0x%04x %s (buf %p) to driver", cmd(buf)->opcode, bt_hci_opcode_to_str(cmd(buf)->opcode), buf);

	err = bt_send(hdev, buf);
	if (err) {
		LOG_ERR("Unable to send to driver (err %d)", err);
		k_sem_give(&hdev->ncmd_sem);
		hci_cmd_done(hdev, cmd(buf)->opcode, BT_HCI_ERR_UNSPECIFIED, buf);
		net_buf_unref(buf);
		bt_tx_irq_raise(hdev);
	}
}

